import fs from 'node:fs';

// Old WordPress product and category URLs, generated by `npm run redirects`.
const catalogRedirects = JSON.parse(
  fs.readFileSync(new URL('./src/data/redirecionamentos.json', import.meta.url), 'utf8'),
);

const isDev = process.env.NODE_ENV === 'development';
const siteUrl = (process.env.NEXT_PUBLIC_SITE_URL || 'https://tritonpiscinas.com.br').replace(
  /\/$/,
  '',
);
// When the site moves to a new domain, the old one (pointed at this same
// deployment) sends every path to it; the path redirects below then apply.
const legacyHost = 'tritonpiscinas.com.br';
const domainRedirects =
  new URL(siteUrl).hostname.replace(/^www\./, '') === legacyHost
    ? []
    : [
        {
          source: '/:path*',
          has: [{ type: 'host', value: '(?:www\\.)?tritonpiscinas\\.com\\.br' }],
          destination: `${siteUrl}/:path*`,
          permanent: true,
        },
      ];
// Images may come from a separate asset host (see README).
const assetOrigin = process.env.NEXT_PUBLIC_ASSET_BASE_URL
  ? new URL(process.env.NEXT_PUBLIC_ASSET_BASE_URL).origin
  : '';

// Without nonces, so every page stays statically generated.
// React needs 'unsafe-eval' only in development.
const policy = ({ img = '', connect = '', style = '', font = '' } = {}) =>
  [
    "default-src 'self'",
    `script-src 'self' 'unsafe-inline'${isDev ? " 'unsafe-eval'" : ''}`,
    `style-src 'self' 'unsafe-inline' ${style}`.trim(),
    `img-src 'self' blob: data: ${img}`.trim(),
    `font-src 'self' ${font}`.trim(),
    `connect-src 'self' ${connect}`.trim(),
    "object-src 'none'",
    "base-uri 'self'",
    "form-action 'self'",
    "frame-ancestors 'none'",
  ].join('; ');
// The Keystatic panel talks to GitHub, shows the editors' avatars and loads
// its Inter font from Google Fonts.
const panelPolicy = policy({
  img: 'https://avatars.githubusercontent.com',
  connect: 'https://api.github.com https://github.com',
  style: 'https://fonts.googleapis.com',
  font: 'https://fonts.gstatic.com',
});

const securityHeaders = [
  { key: 'Content-Security-Policy', value: policy({ img: assetOrigin }) },
  { key: 'Strict-Transport-Security', value: 'max-age=63072000' },
  { key: 'X-Content-Type-Options', value: 'nosniff' },
  { key: 'X-Frame-Options', value: 'DENY' },
  { key: 'Referrer-Policy', value: 'strict-origin-when-cross-origin' },
  { key: 'Permissions-Policy', value: 'camera=(), microphone=(), geolocation=(), payment=()' },
];

const nextConfig = {
  poweredByHeader: false,
  images: {
    formats: ['image/avif', 'image/webp'],
    minimumCacheTTL: 604800,
    remotePatterns: assetOrigin ? [new URL(`${assetOrigin}/**`)] : [],
  },
  async headers() {
    const panel = [
      { key: 'Content-Security-Policy', value: panelPolicy },
      { key: 'X-Robots-Tag', value: 'noindex, nofollow' },
    ];
    // Panel uploads can reuse a file name, so these paths cannot be immutable.
    const publicCache = [
      { key: 'Cache-Control', value: 'public, max-age=86400, stale-while-revalidate=604800' },
    ];
    // Later entries override the same header key.
    return [
      { source: '/(.*)', headers: securityHeaders },
      { source: '/midia/:path*', headers: publicCache },
      { source: '/effects/:path*', headers: publicCache },
      { source: '/keystatic/:path*', headers: panel },
      { source: '/api/keystatic/:path*', headers: panel },
    ];
  },
  async redirects() {
    return [
      ...domainRedirects,
      { source: '/contato-triton-piscinas', destination: '/contato', permanent: true },
      { source: '/perfil-triton-piscina', destination: '/empresa', permanent: true },
      {
        source: '/club-de-regatas-vasco-da-gama-obra-feita-pela-triton-piscinas',
        destination: '/projetos/vasco-da-gama',
        permanent: true,
      },
      {
        source: '/solares-clube-obra-feita-pela-triton-piscinas',
        destination: '/projetos/solares-clube',
        permanent: true,
      },
      {
        source: '/politica-de-privacidade-triton-piscinas',
        destination: '/politicas/privacidade',
        permanent: true,
      },
      {
        source: '/politica-de-entrega-troca-e-devolucao-triton-piscinas',
        destination: '/politicas/entrega',
        permanent: true,
      },
      {
        source: '/termos-de-uso-do-site-triton-piscinas',
        destination: '/politicas/termos',
        permanent: true,
      },
      // The store, cart, checkout and customer accounts were not recreated.
      { source: '/store', destination: '/produtos', permanent: true },
      { source: '/cart', destination: '/produtos', permanent: true },
      { source: '/finalizar-compra', destination: '/produtos', permanent: true },
      { source: '/conta', destination: '/contato', permanent: true },
      { source: '/minha-conta/:path*', destination: '/contato', permanent: true },
      { source: '/cancelamento-do-canal-de-ofertas', destination: '/', permanent: true },
      { source: '/confirmacao-newsletter-mautic', destination: '/', permanent: true },
      ...catalogRedirects.map((redirect) => ({ ...redirect, permanent: true })),
    ];
  },
};
export default nextConfig;
